import fs from "fs";
import path from "path";
import type * as cem from "custom-elements-manifest";
import prettier from "@prettier/sync";

export type TemplateTypesOptions = {
  /** Module whose `JSX` namespace receives `GeneratedIntrinsicElements`, usually the template library's package name */
  moduleName: string;
  /** Path to output directory */
  outdir?: string;
  /** Name of the generated file. When omitted, the file is not written and only the string is returned. */
  fileName?: string;
  /** Tag names to exclude */
  exclude?: string[];
  /** Returns the import path for a component. Defaults to the module path from the manifest. */
  componentTypePath?: (
    name: string,
    tag?: string,
    modulePath?: string,
  ) => string;
};

// Declared inside the JSX namespace without `export`, so they are not visible to importers.
const HELPER_TYPES = [
  "type TemplateIsReadonly<T, K extends keyof T> = (<G>() => G extends { [P in K]: T[P] } ? 1 : 2) extends (<G>() => G extends { -readonly [P in K]: T[P] } ? 1 : 2) ? false : true;",
  "type TemplateProps<E> = { [P in keyof E as P extends string ? (E[P] extends (...args: any[]) => any ? never : TemplateIsReadonly<E, P> extends true ? never : [NonNullable<E[P]>] extends [boolean] ? `?${P}` : `.${P}`) : never]?: E[P] };",
  "type TemplateEvents<M> = { [N in keyof M as `on${N & string}`]?: (e: M[N]) => void };",
  "type TemplateDomEvents = { [N in keyof HTMLElementEventMap as `on${N & string}`]?: (e: HTMLElementEventMap[N]) => void };",
];

/**
 * Generates `JSX.GeneratedIntrinsicElements` for a template library that uses `.prop`,
 * `?bool` and `onevent` bindings. Element keys are derived from each component
 * class, and events come from the manifest. Each entry replaces the template library's
 * own bindings for its tag, so it describes the whole tag.
 *
 * The declaration augments `moduleName`'s `JSX` namespace rather than the global
 * one, so it does not change JSX typings for React, Preact or other libraries.
 *
 * @param manifest - Custom Elements Manifest containing component definitions
 * @param options - Configuration options for the template types
 * @returns The generated declaration source
 */
export function generateTemplateTypes(
  manifest: cem.Package,
  options: TemplateTypesOptions,
): string {
  const {
    moduleName,
    outdir = "./",
    fileName,
    exclude = [],
    componentTypePath,
  } = options;
  const imports = new Map<string, Set<string>>();
  const entries: string[] = [];

  for (const mod of manifest.modules ?? []) {
    for (const declaration of mod.declarations ?? []) {
      const component = declaration as cem.CustomElement;
      const tagName = component.tagName;
      if (!tagName || exclude.includes(tagName)) continue;

      const specifier = componentTypePath
        ? componentTypePath(component.name, tagName, mod.path)
        : mod.path;
      if (!imports.has(specifier)) imports.set(specifier, new Set());
      imports.get(specifier)!.add(component.name);

      const events = (component.events ?? [])
        .filter((event) => event.name)
        .map(
          (event) =>
            `${JSON.stringify(event.name)}: ${event.type?.text ?? "Event"};`,
        );
      const eventPart = events.length
        ? ` & TemplateEvents<{ ${events.join(" ")} }>`
        : "";
      entries.push(
        `      ${JSON.stringify(tagName)}: TemplateProps<${component.name}>${eventPart} & TemplateDomEvents;`,
      );
    }
  }

  const importLines = [...imports].map(
    ([specifier, names]) =>
      `import type { ${Array.from(names).join(", ")} } from ${JSON.stringify(specifier)};`,
  );
  const template = [
    "// Generated by @wc-toolkit/jsx-types. Do not edit.",
    ...importLines,
    "",
    `declare module ${JSON.stringify(moduleName)} {`,
    "  export namespace JSX {",
    ...HELPER_TYPES.map((line) => `    ${line}`),
    "    export interface GeneratedIntrinsicElements {",
    ...entries,
    "    }",
    "  }",
    "}",
    "",
  ].join("\n");

  if (fileName) {
    fs.mkdirSync(outdir, { recursive: true });
    fs.writeFileSync(
      path.join(outdir, fileName),
      prettier.format(template, { parser: "typescript", printWidth: 80 }),
    );
  }

  return template;
}
